/* Read-only Contacts Phase 1C audit vocabulary verification. */
SET NOCOUNT ON;
SELECT N'Phase 1C audit entity allowlist trusted (expect 1)' CheckName,COUNT_BIG(*) FindingCount FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.EntityActionAuditLog') AND name=N'CK_EntityActionAuditLog_EntityType' AND is_disabled=0 AND is_not_trusted=0;
SELECT N'Phase 1C entity tokens present (expect 6)' CheckName,COUNT_BIG(*) FindingCount FROM (VALUES(N'CONTACT_TYPE'),(N'SPECIALTY'),(N'CREDENTIAL_DEFINITION'),(N'CONTACT_CONTACT_TYPE'),(N'CONTACT_SPECIALTY'),(N'CONTACT_CREDENTIAL'))v(token) WHERE EXISTS(SELECT 1 FROM sys.check_constraints c WHERE c.parent_object_id=OBJECT_ID(N'dbo.EntityActionAuditLog') AND c.name=N'CK_EntityActionAuditLog_EntityType' AND c.definition LIKE N'%'''+v.token+N'''%');
SELECT N'invalid Phase 1C audit actions (expect 0)' CheckName,COUNT_BIG(*) FindingCount FROM dbo.EntityActionAuditLog WHERE EntityType IN('CONTACT_TYPE','SPECIALTY','CREDENTIAL_DEFINITION') AND Action NOT IN('CREATED','OVERRIDE_CREATED','UPDATED','ACTIVATED','DEACTIVATED','REMOVED','RESTORED') OR EntityType IN('CONTACT_CONTACT_TYPE','CONTACT_SPECIALTY') AND Action NOT IN('ADDED','REMOVED','RESTORED') OR EntityType='CONTACT_CREDENTIAL' AND Action NOT IN('ADDED','REMOVED','RESTORED','REORDERED');
